import numpy as np, wave
w=wave.open('t8.wav'); raw=np.frombuffer(w.readframes(w.getnframes()),dtype=np.int16).astype(float).reshape(-1,2)
d=raw.mean(axis=1)
SR=44100
def spec(seg):
    n=len(seg); sp=np.abs(np.fft.rfft(seg*np.hanning(n)))
    return sp, np.fft.rfftfreq(n,1/SR)
def peaks(seg,thr=0.15,lo=40,hi=2000):
    sp,f=spec(seg)
    m=(f>=lo)&(f<=hi)
    sp=sp*m; f=f*m
    idx=[i for i in range(1,len(sp)-1) if sp[i]>sp[i-1] and sp[i]>=sp[i+1] and sp[i]>sp.max()*thr]
    idx=sorted(idx,key=lambda i:-sp[i])[:8]
    return sorted(round(f[i],1) for i in idx)
names=['Am','F','C','G','Dm','Bb','E']
PLAN = {
 0:['Am','Am','F','G'],1:['Am','F','C','G'],2:['Am','F','C','G'],3:['Am','F','C','G'],
 4:['Am','F','G','E'],5:['F','G','Am','Am'],6:['Dm','Bb','F','C'],7:['Dm','Bb','C','E'],
 8:['Am','F','C','G'],9:['Am','F','G','E'],10:['Am','F','C','E'],11:['F','G','Am','E']}
# expected note freqs
def freq(n):
    SEMI={'C':0,'C#':1,'D':2,'D#':3,'E':4,'F':5,'F#':6,'G':7,'G#':8,'A':9,'A#':10,'B':11}
    nm=n[:-1]; o=int(n[-1]); m=SEMI[nm]
    return 440.0*2**((m-9+(o-4)*12)/12)
for p in [2,6,10]:
    print('=== pattern',p)
    for bar in range(4):
        s=int((p*4+bar)*1.5*SR)
        seg=d[s:s+int(1.5*SR)]
        pk=peaks(seg)
        c=PLAN[p][bar]
        exp=[round(freq(x)) for x in {'Am':['A2','C3','E3'],'F':['F2','A2','C3'],'C':['C3','E3','G3'],'G':['G2','B2','D3'],
             'Dm':['D3','F3','A3'],'Bb':['A#2','D3','F3'],'E':['E3','G#3','B3']}[c]]
        print(' bar',bar,c,'expected',exp,'found',pk[:6])
EOF"}

